import csv,re,sys
from collections import Counter
rows=list(csv.DictReader(open(sys.argv[1],encoding='utf-8',newline='')))
print("rows",len(rows))
def base(c):
    c=(c or '').strip()
    c=re.sub(r'^IC\s*8-1-26-','',c)
    c=re.sub(r'\([A-Za-z][A-Za-z-]+\)','',c)
    return c.strip()
def head(r):
    s=r.replace('$$','$')
    m=re.search(r'\$\s*(\d[\d,\s]*(?:\.\d+)?)',s)
    if not m: return 0.0
    return float(re.sub(r'[,\s]','',m.group(1)))
cnt=Counter(); tot={}
for r in rows:
    b=base(r['violations']); h=head(r['recommendation'])
    cnt[b]+=1
    if h>0 and b in('16(h)','20(a)(2)'):
        tot.setdefault(b,[]).append(h)
for b,v in tot.items(): print(b,len(v),sum(v),sum(v)/len(v))
print({k:cnt[k] for k in ['16(h)','20(a)(2)']})
EOF
